INSERT INTO `hotfixes`.`spell` (`ID`, `NameSubtext`, `Description`, `AuraDescription`, `VerifiedBuild`) VALUES
(1407001, '', 'Hurl an axe at the target.', 'Hurl an axe at the target.', 69933),
(1407002, '', 'Shoot a barbed arrow that gores the target and keeps bleeding it.', 'Shoot a barbed arrow that gores the target and keeps bleeding it.', 69933),
(1407003, '', 'Hurl a bolt of dark blood at the target.', 'Hurl a bolt of dark blood at the target.', 69933),
(1407004, '', 'Spray acid in every direction, burning nearby enemies.', 'Spray acid in every direction, burning nearby enemies.', 69933),
(1407005, '', 'Brace yourself, taking much less damage for a short time.', 'Brace yourself, taking much less damage for a short time.', 69933),
(1407006, '', 'Batten down: you take less damage for a short time.', 'Batten down: you take less damage for a short time.', 69933),
(1407007, '', 'A bubble of air lets you breathe underwater for a long time.', 'A bubble of air lets you breathe underwater for a long time.', 69933),
(1407008, '', 'Encase yourself in bone armor that absorbs damage.', 'Encase yourself in bone armor that absorbs damage.', 69933),
(1407009, '', 'Send out an arcane eye to scout ahead of you.', 'Send out an arcane eye to scout ahead of you.', 69933),
(1407010, '', 'Throw a serrated axe that bleeds the target.', 'Throw a serrated axe that bleeds the target.', 69933),
(1407011, '', 'Your body radiates heat, burning enemies close to you.', 'Your body radiates heat, burning enemies close to you.', 69933),
(1407012, '', 'A lightning bolt that arcs to nearby enemies.', 'A lightning bolt that arcs to nearby enemies.', 69933),
(1407013, '', 'A cone of arcane anguish hits everything in front of you.', 'A cone of arcane anguish hits everything in front of you.', 69933),
(1407014, '', 'Unleash a flurry of arcane missiles at the target.', 'Unleash a flurry of arcane missiles at the target.', 69933),
(1407015, '', 'Blink forward and leave a nova of arcane energy behind.', 'Blink forward and leave a nova of arcane energy behind.', 69933),
(1407016, '', 'A dome of arcane force shields you from damage.', 'A dome of arcane force shields you from damage.', 69933),
(1407017, '', 'Whirl a storm of bones around you, hitting all nearby enemies.', 'Whirl a storm of bones around you, hitting all nearby enemies.', 69933),
(1407018, '', 'Spikes of bone burst out and stun enemies near you.', 'Spikes of bone burst out and stun enemies near you.', 69933),
(1407019, '', 'Throw a grenade that explodes in fire.', 'Throw a grenade that explodes in fire.', 69933),
(1407020, '', 'Charge forward, knocking enemies aside.', 'Charge forward, knocking enemies aside.', 69933),
(1407021, '', 'Crush the area with the weight of the abyss.', 'Crush the area with the weight of the abyss.', 69933),
(1407022, '', 'Halazzi''s breath mends an ally.', 'Halazzi''s breath mends an ally.', 69933),
(1407023, '', 'A blessing of Ula''tek empowers you and your allies.', 'A blessing of Ula''tek empowers you and your allies.', 69933),
(1407024, '', 'Roots dig into the target and hold it.', 'Roots dig into the target and hold it.', 69933),
(1407025, '', 'A heavy arcane blast.', 'A heavy arcane blast.', 69933),
(1407026, '', 'Dissolve incoming arcane magic and shrug off harm.', 'Dissolve incoming arcane magic and shrug off harm.', 69933),
(1407027, '', 'Arcane orbs rain down on the target area.', 'Arcane orbs rain down on the target area.', 69933),
(1407028, '', 'Wield the flames of Jan''alai and set the area ablaze.', 'Wield the flames of Jan''alai and set the area ablaze.', 69933),
(1407029, '', 'A mighty bulwark: you take far less damage for a short time.', 'A mighty bulwark: you take far less damage for a short time.', 69933);
